export{};let threadParams:any={};for await(const line of console){const m=JSON.parse(line);if(m.id===undefined)continue;let result:any={};if(m.method==="initialize")result={userAgent:"fake",received:m.params};if(m.method==="account/read")result={account:{type:"chatgpt",planType:"pro"}};if(m.method==="account/login/start")result={type:m.params.type,deviceCode:"ephemeral-device-code"};if(m.method==="thread/start"){threadParams=m.params;result={thread:{id:"thread-1"}}}if(m.method==="turn/start"){result={turn:{id:"turn-1"},usage:{inputTokens:2,outputTokens:1}};if(m.params.model==="timer-model"){console.log(JSON.stringify({id:m.id,result}));setTimeout(()=>{console.log(JSON.stringify({method:"item/agentMessage/delta",params:{delta:"answer"}}));console.log(JSON.stringify({method:"turn/completed",params:{threadId:"thread-1",turn:{id:"turn-1",status:"completed"}}}))},10);continue}if(m.params.model==="reasoning-model"){for(const [index,delta]of[[0,"Check the"],[0," parity."],[1,"Then answer."]]as const)console.log(JSON.stringify({method:"item/reasoning/summaryTextDelta",params:{threadId:"thread-1",turnId:"turn-1",itemId:"r1",summaryIndex:index,delta}}));console.log(JSON.stringify({method:"item/agentMessage/delta",params:{delta:`ans|${m.params.effort}|${m.params.summary}`}}))}else if(m.params.model==="tool-model"||(m.params.model==="tool-disabled-model"&&threadParams.config?.default_tools_enabled!==false))console.log(JSON.stringify({method:"item/commandExecution/request",params:{type:"shell"}}));else console.log(JSON.stringify({method:"item/agentMessage/delta",params:{delta:"answer"}}));console.log(JSON.stringify({method:"turn/completed",params:{threadId:"thread-1",turn:{id:"turn-1",status:"completed"}}}))}if(m.method==="model/list")result={data:[{id:"codex-test"}]};if(m.method==="account/rateLimits/read")result={remaining:null};console.log(JSON.stringify({id:m.id,result}))}
